def _df(include_adj: bool) -> pl.DataFrame:
    n = len(_FIXTURE)
    df = pl.DataFrame({
        "code": ["688553"] * n,
        "date": [date.fromisoformat(r[0]) for r in _FIXTURE],
        "open": [r[1] for r in _FIXTURE],
        "high": [r[2] for r in _FIXTURE],
        "low": [r[3] for r in _FIXTURE],
        "close": [r[4] for r in _FIXTURE],
        "volume": [float(r[5]) for r in _FIXTURE],
        "pre_close": [r[6] for r in _FIXTURE],
    })
    if include_adj:
        df = df.with_columns(pl.Series("adj_factor", [float(r[7]) for r in _FIXTURE]))
    return df


def test_qfq_scale_ratio():
    """scale = adj_factor / 最新因子：除权日前 <1，除权日后 =1。"""
    df = _df(include_adj=True)
    expr = b1_mod._qfq_scale(df)
    assert expr is not None
    got = df.with_columns(expr.alias("s"))["s"].to_list()
    latest = df["adj_factor"][-1]
    assert got[-1] == pytest.approx(1.0)
    # 06-16（除权日前）：因子 1.0676 → scale = 1.0676/1.597 ≈ 0.6685
    idx = df["date"].to_list().index(date(2026, 6, 16))
    assert got[idx] == pytest.approx(1.0676 / latest)


def test_qfq_scale_none_without_column():
    """无 adj_factor 列（旧数据/测试 fixture）：返回 None，用原价。"""
    df = _df(include_adj=False)
    assert b1_mod._qfq_scale(df) is None


def test_688553_hits_with_adj_factor():
    """带真实 adj_factor：多空线按前复权（11.83）→ 全部条件通过 → 命中。"""
    df = _df(include_adj=True)
    out = compute_b1_columns(df)
    g = out.partition_by("code")[0]
    assert g["_b1_signal"][-1] is True, "前复权下 688553 应命中（TDX 一致）"


def test_688553_misses_without_adj_factor():
    """无 adj_factor（未复权）：多空线 12.87 虚高 → 不命中（原 bug 复现）。"""
    df = _df(include_adj=False)
    out = compute_b1_columns(df)
    g = out.partition_by("code")[0]
    assert g["_b1_signal"][-1] is False, "未复权下 688553 不命中（多空线虚高）"
